//! WireGuard (lane F): tunnels and peers from the config store, applied to
//! the kernel at boot (phase "interfaces", after lane C) and after every
//! change from the web UI / API.
//!
//! - Keys are Curve25519 pairs generated here (no `wg genkey` needed);
//!   private keys stay in the store and are never returned by the API.
//!   Road-warrior peers get a key pair generated by Patronus so the client
//!   config / QR code can be exported; a site-to-site peer is added with the
//!   other side's public key instead.
//! - Each enabled `wg_interfaces` row becomes a kernel `wireguard` link
//!   tagged with ifalias [`WG_ALIAS`] (so Patronus never touches a tunnel it
//!   did not create, e.g. one brought up with wg-quick), configured with
//!   `wg syncconf` from a 0600 file in the state dir (full state: peers
//!   not in the store are removed), its addresses and MTU, and a route
//!   (protocol [`WG_PROTO`]) for every peer network outside the tunnel
//!   subnet. Links/routes of deleted or disabled tunnels are removed.
//! - The listen ports are opened on the WAN by the firewall applier
//!   (`patronus_firewall` reads `wg_interfaces`); what tunnel traffic may
//!   reach is up to firewall rules on the tunnel interface (e.g. `wg0`).

use crate::lan::{check_description, db_err, invalid, now};
use crate::linkstate::{argv, Cmd, KernelState, SystemCmd};
use crate::vpn::{check_endpoint, check_host, check_name, check_networks, networks, split_list};
use async_trait::async_trait;
use base64::{engine::general_purpose::STANDARD as B64, Engine};
use ipnetwork::IpNetwork;
use patronus_config::applier::{Applier, ApplyReport, Phase};
use patronus_config::store::ConfigStore;
use patronus_core::{Error, Result};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sqlx::Row;
use std::collections::BTreeSet;
use std::net::IpAddr;
use std::path::PathBuf;
use std::sync::Arc;

/// ifalias of every WireGuard link Patronus created.
pub const WG_ALIAS: &str = "patronus-wg";
/// Route protocol of the peer routes Patronus installs.
pub const WG_PROTO: &str = "249";
/// Default listen port of the first tunnel.
pub const DEFAULT_PORT: u16 = 51820;

// ---------------------------------------------------------------------------
// keys
// ---------------------------------------------------------------------------

/// A new (private, public) key pair, base64 like `wg genkey | wg pubkey`.
pub fn generate_keypair() -> (String, String) {
    let secret = x25519_dalek::StaticSecret::random_from_rng(rand::rngs::OsRng);
    let public = x25519_dalek::PublicKey::from(&secret);
    (B64.encode(secret.to_bytes()), B64.encode(public.as_bytes()))
}

/// A new pre-shared key (`wg genpsk`).
pub fn generate_psk() -> String {
    use rand::RngCore;
    let mut k = [0u8; 32];
    rand::rngs::OsRng.fill_bytes(&mut k);
    B64.encode(k)
}

fn key_bytes(what: &str, k: &str) -> Result<[u8; 32]> {
    let v = B64
        .decode(k.trim())
        .map_err(|_| invalid(format!("{what}: not a base64 WireGuard key")))?;
    v.try_into()
        .map_err(|_| invalid(format!("{what}: a WireGuard key is 32 bytes")))
}

/// Validate a base64 key and return it normalised.
pub fn check_key(what: &str, k: &str) -> Result<String> {
    Ok(B64.encode(key_bytes(what, k)?))
}

/// The public key of a private key (`wg pubkey`).
pub fn public_key(private: &str) -> Result<String> {
    let secret = x25519_dalek::StaticSecret::from(key_bytes("private key", private)?);
    Ok(B64.encode(x25519_dalek::PublicKey::from(&secret).as_bytes()))
}

