#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct WgInterface {
    pub name: String,
    pub enabled: bool,
    #[serde(skip_serializing, default)]
    pub private_key: String,
    pub public_key: String,
    pub listen_port: u16,
    pub addresses: String,
    pub mtu: Option<u32>,
    pub endpoint: Option<String>,
    pub client_dns: Option<String>,
    pub client_allowed_ips: String,
    pub description: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct WgPeer {
    pub id: i64,
    pub interface: String,
    pub name: String,
    pub enabled: bool,
    pub public_key: String,
    #[serde(skip_serializing, default)]
    pub private_key: Option<String>,
    #[serde(skip_serializing, default)]
    pub preshared_key: Option<String>,
    pub allowed_ips: String,
    pub endpoint: Option<String>,
    pub persistent_keepalive: Option<u16>,
    pub description: Option<String>,
    /// Patronus holds this peer's private key: its client config can be
    /// exported.
    pub exportable: bool,
    pub has_psk: bool,
}

pub async fn list_interfaces(store: &ConfigStore) -> Result<Vec<WgInterface>> {
    let rows = sqlx::query(
        "SELECT name, enabled, private_key, listen_port, addresses, mtu, endpoint, client_dns,
                client_allowed_ips, description FROM wg_interfaces ORDER BY name",
    )
    .fetch_all(store.pool()?)
    .await
    .map_err(db_err("read wg_interfaces"))?;
    let mut out = Vec::new();
    for r in rows {
        let private_key: String = r.get(2);
        out.push(WgInterface {
            name: r.get(0),
            enabled: r.get::<i64, _>(1) != 0,
            public_key: public_key(&private_key).unwrap_or_default(),
            private_key,
            listen_port: r.get::<i64, _>(3) as u16,
            addresses: r.get(4),
            mtu: r.get::<Option<i64>, _>(5).map(|m| m as u32),
            endpoint: r.get(6),
            client_dns: r.get(7),
            client_allowed_ips: r.get(8),
            description: r.get(9),
        });
    }
    Ok(out)
}

pub async fn list_peers(store: &ConfigStore) -> Result<Vec<WgPeer>> {
    let rows = sqlx::query(
        "SELECT id, interface, name, enabled, public_key, private_key, preshared_key, allowed_ips,
                endpoint, persistent_keepalive, description FROM wg_peers ORDER BY interface, id",
    )
    .fetch_all(store.pool()?)
    .await
    .map_err(db_err("read wg_peers"))?;
    Ok(rows
        .iter()
        .map(|r| {
            let private_key: Option<String> = r.get(5);
            let preshared_key: Option<String> = r.get(6);
            WgPeer {
                id: r.get(0),
                interface: r.get(1),
                name: r.get(2),
                enabled: r.get::<i64, _>(3) != 0,
                public_key: r.get(4),
                exportable: private_key.is_some(),
                has_psk: preshared_key.is_some(),
                private_key,
                preshared_key,
                allowed_ips: r.get(7),
                endpoint: r.get(8),
                persistent_keepalive: r.get::<Option<i64>, _>(9).map(|k| k as u16),
                description: r.get(10),
            }
        })
        .collect())
}

/// What the API / UI sends for a tunnel (missing fields keep their value
/// on edit).
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct InterfaceInput {
    #[serde(default)]
    pub name: Option<String>,
    #[serde(default)]
    pub enabled: Option<bool>,
    #[serde(default)]
    pub listen_port: Option<u16>,
    #[serde(default)]
    pub addresses: Option<String>,
    #[serde(default)]
    pub mtu: Option<u32>,
    #[serde(default)]
    pub endpoint: Option<String>,
    #[serde(default)]
    pub client_dns: Option<String>,
    #[serde(default)]
    pub client_allowed_ips: Option<String>,
    #[serde(default)]
    pub description: Option<String>,
    /// Replace the key pair (peers must get the new public key).
    #[serde(default)]
    pub regenerate_key: Option<bool>,
}

/// `kind: WireGuardTunnel` from a repository: the tunnel form's fields
/// (`listen_port, addresses, mtu, endpoint, client_dns, client_allowed_ips,
/// enabled, description`) and its peers (`name, public_key, allowed_ips,
/// endpoint, persistent_keepalive, preshared_key, enabled, description`).
/// The tunnel's private key is generated by Patronus and never in git; the
/// peer list is authoritative (peers not listed are removed). A peer
/// without `public_key` is a road warrior whose key pair Patronus makes.
pub async fn gitops_upsert_tunnel(
    store: &ConfigStore,
    name: &str,
    spec: &serde_json::Value,
) -> Result<()> {
    #[derive(Deserialize)]
    struct Spec {
        #[serde(flatten)]
        iface: InterfaceInput,
        #[serde(default)]
        peers: Vec<PeerInput>,
    }
    let mut s: Spec = serde_json::from_value(spec.clone())
        .map_err(|e| invalid(format!("WireGuard tunnel {name}: {e}")))?;
    for p in &s.peers {
        if opt(&p.name).is_none() {
            return Err(invalid(format!(
                "WireGuard tunnel {name}: every peer needs a name"
            )));
        }
    }
    s.iface.name = Some(name.to_string());
    s.iface.regenerate_key = None;
    let exists = list_interfaces(store).await?.iter().any(|i| i.name == name);
    save_interface(store, exists.then_some(name), &s.iface).await?;
    let current: Vec<WgPeer> = list_peers(store)
        .await?
        .into_iter()
        .filter(|p| p.interface == name)
        .collect();
    for c in &current {
        if !s
            .peers
            .iter()
            .any(|p| opt(&p.name) == Some(c.name.as_str()))
        {
            delete_peer(store, c.id).await?;
        }
    }
    for mut p in s.peers {
        p.interface = Some(name.to_string());
        let pname = opt(&p.name).unwrap_or_default().to_string();
        let cur = current.iter().find(|c| c.name == pname);
        save_peer(store, cur.map(|c| c.id), &p).await?;
    }
    Ok(())
}

/// A Linux interface name for a tunnel: 1-15 of `[A-Za-z0-9_-]`, starting
/// with a letter.
pub fn check_ifname(s: &str) -> Result<String> {
    let s = s.trim();
    let ok = !s.is_empty()
        && s.len() <= 15
        && s.chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
        && s.chars().next().is_some_and(|c| c.is_ascii_alphabetic());
    if ok {
        Ok(s.to_string())
    } else {
        Err(invalid(format!(
            "tunnel interface name {s:?} (1-15 letters/digits/_/-, starting with a letter, e.g. wg0)"
        )))
    }
}

fn opt(s: &Option<String>) -> Option<&str> {
    s.as_deref().map(str::trim).filter(|v| !v.is_empty())
}

/// The public endpoint clients connect to: a host / address, optionally
/// with a port when the WAN forwards another port to the tunnel.
fn check_public_endpoint(e: &str) -> Result<String> {
    let e = e.trim();
    if e.starts_with('[') || (e.contains(':') && e.matches(':').count() == 1) {
        check_endpoint("public endpoint", e)
    } else {
        check_host("public endpoint", e)
    }
}

/// Create (`existing` = None) or edit a tunnel. Returns its name.
pub async fn save_interface(
    store: &ConfigStore,
    existing: Option<&str>,
    i: &InterfaceInput,
) -> Result<String> {
    let all = list_interfaces(store).await?;
    let cur = match existing {
        Some(n) => Some(
            all.iter()
                .find(|x| x.name == n)
                .cloned()
                .ok_or_else(|| Error::Config(format!("no WireGuard tunnel {n:?}")))?,
        ),
        None => None,
    };
    let name = match (opt(&i.name), &cur) {
        (Some(n), _) => check_ifname(n)?,
        (None, Some(c)) => c.name.clone(),
        (None, None) => (0..)
            .map(|n| format!("wg{n}"))
            .find(|n| !all.iter().any(|x| &x.name == n))
            .unwrap_or_else(|| "wg0".into()),
    };
    if all
        .iter()
        .any(|x| x.name == name && Some(x.name.as_str()) != existing)
    {
        return Err(invalid(format!("tunnel: {name} already exists")));
    }
    let listen_port = match (i.listen_port, &cur) {
        (Some(0), _) => return Err(invalid("listen port: 1-65535")),
        (Some(p), _) => p,
        (None, Some(c)) => c.listen_port,
        (None, None) => (DEFAULT_PORT..)
            .find(|p| !all.iter().any(|x| x.listen_port == *p))
            .unwrap_or(DEFAULT_PORT),
    };
    if let Some(other) = all
        .iter()
        .find(|x| x.listen_port == listen_port && Some(x.name.as_str()) != existing)
    {
        return Err(invalid(format!(
            "listen port {listen_port} is already used by {}",
            other.name
        )));
    }
    let addresses = match (&i.addresses, &cur) {
        (Some(a), _) => check_networks("tunnel addresses", a, true)?,
        (None, Some(c)) => c.addresses.clone(),
        (None, None) => String::new(),
    };
    let mtu = match (i.mtu, &cur) {
        (Some(0), _) => None,
        (Some(m), _) if !(1280..=9000).contains(&m) => {
            return Err(invalid("MTU: 1280-9000 (0 = default 1420)"))
        }
        (Some(m), _) => Some(m),
        (None, Some(c)) => c.mtu,
        (None, None) => None,
    };
    let endpoint = match (&i.endpoint, &cur) {
        (Some(e), _) if e.trim().is_empty() => None,
        (Some(e), _) => Some(check_public_endpoint(e)?),
        (None, Some(c)) => c.endpoint.clone(),
        (None, None) => None,
    };
    let client_dns = match (&i.client_dns, &cur) {
        (Some(d), _) if d.trim().is_empty() => None,
        (Some(d), _) => Some(
            crate::lan::parse_ip_list("client DNS", d)?
                .iter()
                .map(|a| a.to_string())
                .collect::<Vec<_>>()
                .join(", "),
        ),
        (None, Some(c)) => c.client_dns.clone(),
        (None, None) => None,
    };
    let client_allowed_ips = match (&i.client_allowed_ips, &cur) {
        (Some(a), _) => check_networks("client allowed IPs", a, false)?,
        (None, Some(c)) => c.client_allowed_ips.clone(),
        (None, None) => "0.0.0.0/0, ::/0".into(),
    };
    let description = match (&i.description, &cur) {
        (Some(d), _) => check_description(Some(d))?,
        (None, Some(c)) => c.description.clone(),
        (None, None) => None,
    };
    let enabled = i
        .enabled
        .or(cur.as_ref().map(|c| c.enabled))
        .unwrap_or(true);
    let private_key = match &cur {
        Some(c) if !i.regenerate_key.unwrap_or(false) => c.private_key.clone(),
        _ => generate_keypair().0,
    };
    let sql = if existing.is_some() {
        "UPDATE wg_interfaces SET name=?, enabled=?, private_key=?, listen_port=?, addresses=?,
            mtu=?, endpoint=?, client_dns=?, client_allowed_ips=?, description=?, updated_at=?
         WHERE name=?"
    } else {
        "INSERT INTO wg_interfaces (name, enabled, private_key, listen_port, addresses, mtu,
            endpoint, client_dns, client_allowed_ips, description, updated_at)
         VALUES (?,?,?,?,?,?,?,?,?,?,?)"
    };
    let mut q = sqlx::query(sql)
        .bind(&name)
        .bind(enabled as i64)
        .bind(&private_key)
        .bind(listen_port as i64)
        .bind(&addresses)
        .bind(mtu.map(|m| m as i64))
        .bind(&endpoint)
        .bind(&client_dns)
        .bind(&client_allowed_ips)
        .bind(&description)
        .bind(now());
    if let Some(old) = existing {
        q = q.bind(old);
    }
    q.execute(store.pool()?)
        .await
        .map_err(db_err("save tunnel"))?;
    Ok(name)
}

pub async fn delete_interface(store: &ConfigStore, name: &str) -> Result<bool> {
    let r = sqlx::query("DELETE FROM wg_interfaces WHERE name = ?")
        .bind(name)
        .execute(store.pool()?)
        .await
        .map_err(db_err("delete tunnel"))?;
    Ok(r.rows_affected() > 0)
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct PeerInput {
    #[serde(default)]
    pub interface: Option<String>,
    #[serde(default)]
    pub name: Option<String>,
    #[serde(default)]
    pub enabled: Option<bool>,
    /// The peer's public key. Empty on create = Patronus generates the
    /// peer's key pair (a client whose config is exported from here).
    #[serde(default)]
    pub public_key: Option<String>,
    /// Empty on create = the next free address(es) of the tunnel subnet.
    #[serde(default)]
    pub allowed_ips: Option<String>,
    #[serde(default)]
    pub endpoint: Option<String>,
    #[serde(default)]
    pub persistent_keepalive: Option<u16>,
    /// true = generate a pre-shared key, false = remove it.
    #[serde(default)]
    pub preshared_key: Option<bool>,
    #[serde(default)]
    pub description: Option<String>,
}

/// The next free host address in each of the tunnel's subnets (the first
/// IPv4 and the first IPv6 one), as /32 and /128. `used` are the other
/// peers' allowed IPs; only host-sized entries count as taken.
pub fn next_free_addresses(tunnel_addrs: &str, used: &[IpNetwork]) -> Vec<IpNetwork> {
    let mut out = Vec::new();
    let mut fams = BTreeSet::new();
    for net in networks(tunnel_addrs) {
        if !fams.insert(net.is_ipv4()) {
            continue;
        }
        let taken = |ip: IpAddr| {
            ip == net.ip()
                || used
                    .iter()
                    .any(|u| u.contains(ip) && u.prefix() >= if u.is_ipv4() { 30 } else { 120 })
        };
        let pick = match net {
            IpNetwork::V4(n) => n
                .iter()
                .skip(1)
                .take((n.size() as usize).saturating_sub(2))
                .map(IpAddr::V4)
                .find(|ip| !taken(*ip))
                .and_then(|ip| IpNetwork::new(ip, 32).ok()),
            IpNetwork::V6(n) => {
                let base = u128::from(n.network());
                (1u128..=65535)
                    .map(|k| std::net::Ipv6Addr::from(base + k))
                    .filter(|ip| n.contains(*ip))
                    .map(IpAddr::V6)
                    .find(|ip| !taken(*ip))
                    .and_then(|ip| IpNetwork::new(ip, 128).ok())
            }
        };
        out.extend(pick);
    }
    out
}

/// Create (`id` = None) or edit a peer. Returns its id.
pub async fn save_peer(store: &ConfigStore, id: Option<i64>, p: &PeerInput) -> Result<i64> {
    let peers = list_peers(store).await?;
    let ifaces = list_interfaces(store).await?;
    let cur = match id {
        Some(id) => Some(
            peers
                .iter()
                .find(|x| x.id == id)
                .cloned()
                .ok_or_else(|| Error::Config(format!("no WireGuard peer {id}")))?,
        ),
        None => None,
    };
    let iface_name = match (opt(&p.interface), &cur) {
        (Some(n), _) => n.to_string(),
        (None, Some(c)) => c.interface.clone(),
        (None, None) => ifaces
            .first()
            .map(|i| i.name.clone())
            .ok_or_else(|| invalid("peer: create a WireGuard tunnel first"))?,
    };
    let iface = ifaces
        .iter()
        .find(|i| i.name == iface_name)
        .ok_or_else(|| invalid(format!("peer: no tunnel {iface_name:?}")))?;
    let name = match (opt(&p.name), &cur) {
        (Some(n), _) => check_name("peer name", n, 48)?,
        (None, Some(c)) => c.name.clone(),
        (None, None) => return Err(invalid("peer: a name is required")),
    };
    if peers
        .iter()
        .any(|x| x.interface == iface_name && x.name == name && Some(x.id) != id)
    {
        return Err(invalid(format!(
            "peer: {name:?} already exists on {iface_name}"
        )));
    }
    let (public_key, private_key) = match (opt(&p.public_key), &cur) {
        (Some(k), _) => {
            let k = check_key("peer public key", k)?;
            let keep_priv = cur
                .as_ref()
                .filter(|c| c.public_key == k)
                .and_then(|c| c.private_key.clone());
            (k, keep_priv)
        }
        (None, Some(c)) => (c.public_key.clone(), c.private_key.clone()),
        (None, None) => {
            let (private, public) = generate_keypair();
            (public, Some(private))
        }
    };
    if public_key == iface.public_key {
        return Err(invalid("peer public key: that is this tunnel's own key"));
    }
    if peers
        .iter()
        .any(|x| x.interface == iface_name && x.public_key == public_key && Some(x.id) != id)
    {
        return Err(invalid(
            "peer public key: another peer of this tunnel has it",
        ));
    }
    let allowed_ips = match (&p.allowed_ips, &cur) {
        (Some(a), _) if !a.trim().is_empty() => check_networks("allowed IPs", a, false)?,
        (None, Some(c)) => c.allowed_ips.clone(),
        _ => {
            let used: Vec<IpNetwork> = peers
                .iter()
                .filter(|x| x.interface == iface_name && Some(x.id) != id)
                .flat_map(|x| networks(&x.allowed_ips))
                .collect();
            let v = next_free_addresses(&iface.addresses, &used);
            if v.is_empty() {
                return Err(invalid(
                    "allowed IPs: give the peer's tunnel address (the tunnel has no address \
                     to pick one from)",
                ));
            }
            v.iter()
                .map(|n| n.to_string())
                .collect::<Vec<_>>()
                .join(", ")
        }
    };
    let endpoint = match (&p.endpoint, &cur) {
        (Some(e), _) if e.trim().is_empty() => None,
        (Some(e), _) => Some(check_endpoint("peer endpoint", e)?),
        (None, Some(c)) => c.endpoint.clone(),
        (None, None) => None,
    };
    let persistent_keepalive = match (p.persistent_keepalive, &cur) {
        (Some(0), _) => None,
        (Some(k), _) => Some(k),
        (None, Some(c)) => c.persistent_keepalive,
        (None, None) => None,
    };
    let preshared_key = match (p.preshared_key, &cur) {
        (Some(true), Some(c)) if c.preshared_key.is_some() => c.preshared_key.clone(),
        (Some(true), _) => Some(generate_psk()),
        (Some(false), _) => None,
        (None, Some(c)) => c.preshared_key.clone(),
        (None, None) => None,
    };
    let description = match (&p.description, &cur) {
        (Some(d), _) => check_description(Some(d))?,
        (None, Some(c)) => c.description.clone(),
        (None, None) => None,
    };
    let enabled = p
        .enabled
        .or(cur.as_ref().map(|c| c.enabled))
        .unwrap_or(true);
    let sql = if id.is_some() {
        "UPDATE wg_peers SET interface=?, name=?, enabled=?, public_key=?, private_key=?,
            preshared_key=?, allowed_ips=?, endpoint=?, persistent_keepalive=?, description=?,
            updated_at=? WHERE id=?"
    } else {
        "INSERT INTO wg_peers (interface, name, enabled, public_key, private_key, preshared_key,
            allowed_ips, endpoint, persistent_keepalive, description, updated_at, id)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?)"
    };
    let r = sqlx::query(sql)
        .bind(&iface_name)
        .bind(&name)
        .bind(enabled as i64)
        .bind(&public_key)
        .bind(&private_key)
        .bind(&preshared_key)
        .bind(&allowed_ips)
        .bind(&endpoint)
        .bind(persistent_keepalive.map(|k| k as i64))
        .bind(&description)
        .bind(now())
        .bind(id)
        .execute(store.pool()?)
        .await
        .map_err(db_err("save peer"))?;
    Ok(id.unwrap_or_else(|| r.last_insert_rowid()))
}

pub async fn delete_peer(store: &ConfigStore, id: i64) -> Result<bool> {
    let r = sqlx::query("DELETE FROM wg_peers WHERE id = ?")
        .bind(id)
        .execute(store.pool()?)
        .await
        .map_err(db_err("delete peer"))?;
    Ok(r.rows_affected() > 0)
}

/// The WireGuard client config (`wg-quick` format) of a peer whose key
/// pair Patronus generated. `None` if the peer's private key is not held
/// here (a site-to-site peer added with its own public key).
pub fn client_config(iface: &WgInterface, peer: &WgPeer) -> Result<Option<String>> {
    let Some(private) = &peer.private_key else {
        return Ok(None);
    };
    let Some(host) = &iface.endpoint else {
        return Err(invalid(format!(
            "client config: set the public endpoint (host name or WAN address) of {} first",
            iface.name
        )));
    };
    let endpoint = if host.starts_with('[') || host.matches(':').count() == 1 {
        host.clone()
    } else if host.contains(':') {
        format!("[{host}]:{}", iface.listen_port)
    } else {
        format!("{host}:{}", iface.listen_port)
    };
    let mut c = format!(
        "# {} on {} (Patronus)\n[Interface]\nPrivateKey = {private}\nAddress = {}\n",
        peer.name, iface.name, peer.allowed_ips
    );
    if let Some(d) = &iface.client_dns {
        c.push_str(&format!("DNS = {d}\n"));
    }
    c.push_str(&format!("\n[Peer]\nPublicKey = {}\n", iface.public_key));
    if let Some(psk) = &peer.preshared_key {
        c.push_str(&format!("PresharedKey = {psk}\n"));
    }
    c.push_str(&format!(
        "AllowedIPs = {}\nEndpoint = {endpoint}\nPersistentKeepalive = 25\n",
        iface.client_allowed_ips
    ));
    Ok(Some(c))
}

// ---------------------------------------------------------------------------
// applier
// ---------------------------------------------------------------------------

/// `wg setconf` file of one tunnel (no wg-quick keys: addresses, routes
/// and MTU are set by the applier).
pub fn render_setconf(iface: &WgInterface, peers: &[&WgPeer]) -> String {
    let mut c = format!(
        "# {} (WireGuard {}). Do not edit: regenerated from /var/lib/patronus/config.db.\n\
         [Interface]\nPrivateKey = {}\nListenPort = {}\n",
        crate::lan::MARKER,
        iface.name,
        iface.private_key,
        iface.listen_port
    );
    for p in peers {
        c.push_str(&format!(
            "\n# {}\n[Peer]\nPublicKey = {}\n",
            p.name, p.public_key
        ));
        if let Some(k) = &p.preshared_key {
            c.push_str(&format!("PresharedKey = {k}\n"));
        }
        let ips = split_list(&p.allowed_ips).join(", ");
        if !ips.is_empty() {
            c.push_str(&format!("AllowedIPs = {ips}\n"));
        }
        if let Some(e) = &p.endpoint {
            c.push_str(&format!("Endpoint = {e}\n"));
        }
        if let Some(k) = p.persistent_keepalive {
            c.push_str(&format!("PersistentKeepalive = {k}\n"));
        }
    }
    c
}

/// Peer networks that need a route via the tunnel: everything not already
/// on-link through the tunnel's own addresses; default routes are never
/// installed (a peer with 0.0.0.0/0 is a client's view, not a router's).
pub fn peer_routes(
    iface: &WgInterface,
    peers: &[&WgPeer],
    rep: &mut ApplyReport,
) -> Vec<IpNetwork> {
    let own = networks(&iface.addresses);
    let mut out: Vec<IpNetwork> = Vec::new();
    for p in peers {
        for n in networks(&p.allowed_ips) {
            if n.prefix() == 0 {
                rep.warn(format!(
                    "{} peer {:?}: allowed IPs {n} is a default route; not routed through the \
                     tunnel (use a gateway / policy routing for that)",
                    iface.name, p.name
                ));
                continue;
            }
            let net = IpNetwork::new(n.network(), n.prefix()).unwrap_or(n);
            if own.iter().any(|o| {
                o.is_ipv4() == net.is_ipv4()
                    && o.prefix() <= net.prefix()
                    && o.contains(net.network())
            }) {
                continue;
            }
            if !out.contains(&net) {
                out.push(net);
            }
        }
    }
    out
}

/// Kernel route destination as `ip -j route` prints it -> CIDR.
fn route_cidr(dst: &str, v6: bool) -> String {
    if dst.contains('/') {
        dst.to_string()
    } else if v6 {
        format!("{dst}/128")
    } else {
        format!("{dst}/32")
    }
}

#[derive(Clone)]
pub struct WireGuardApplier {
    cmd: Arc<dyn Cmd>,
    conf_dir: PathBuf,
}

impl Default for WireGuardApplier {
    fn default() -> Self {
        Self::new(
            Arc::new(SystemCmd),
            crate::supervise::NetPaths::default()
                .state_dir
                .join("wireguard"),
        )
    }
}

impl WireGuardApplier {
    pub fn new(cmd: Arc<dyn Cmd>, conf_dir: PathBuf) -> Self {
        Self { cmd, conf_dir }
    }

    async fn ip(&self, args: &[&str]) -> Result<String> {
        self.cmd.run("ip", &argv(args)).await
    }

    fn write_conf(&self, name: &str, content: &str) -> Result<PathBuf> {
        use std::io::Write;
        use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
        std::fs::DirBuilder::new()
            .recursive(true)
            .mode(0o700)
            .create(&self.conf_dir)
            .map_err(|e| Error::Config(format!("{}: {e}", self.conf_dir.display())))?;
        let path = self.conf_dir.join(format!("{name}.conf"));
        let tmp = self.conf_dir.join(format!(".{name}.conf.new"));
        let _ = std::fs::remove_file(&tmp);
        let mut f = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&tmp)
            .map_err(|e| Error::Config(format!("{}: {e}", tmp.display())))?;
        f.write_all(content.as_bytes())
            .map_err(|e| Error::Config(format!("{}: {e}", tmp.display())))?;
        std::fs::rename(&tmp, &path)
            .map_err(|e| Error::Config(format!("{}: {e}", path.display())))?;
        Ok(path)
    }

    async fn owned_routes(&self, dev: &str) -> Result<Vec<String>> {
        let mut out = Vec::new();
        for (fam, v6) in [("-4", false), ("-6", true)] {
            let o = match self
                .ip(&["-j", fam, "route", "show", "dev", dev, "proto", WG_PROTO])
                .await
            {
                Ok(o) => o,
                Err(e) if v6 => {
                    tracing::debug!("ip -6 route: {e}");
                    continue;
                }
                Err(e) => return Err(e),
            };
            let txt = if o.trim().is_empty() {
                "[]"
            } else {
                o.as_str()
            };
            let v: Vec<Value> = serde_json::from_str(txt)
                .map_err(|e| Error::Network(format!("parse ip route: {e}")))?;
            for r in v {
                if let Some(d) = r.get("dst").and_then(Value::as_str) {
                    out.push(route_cidr(d, v6));
                }
            }
        }
        Ok(out)
    }

    async fn apply_one(
        &self,
        iface: &WgInterface,
        peers: &[&WgPeer],
        k: &KernelState,
        rep: &mut ApplyReport,
    ) -> Result<()> {
        let n = iface.name.as_str();
        match k.get(n) {
            Some(l)
                if l.kind.as_deref() == Some("wireguard")
                    && l.alias.as_deref() == Some(WG_ALIAS) => {}
            Some(_) => {
                rep.warn(format!(
                    "{n} already exists and was not created by Patronus; tunnel {n} not applied"
                ));
                return Ok(());
            }
            None => {
                self.ip(&["link", "add", "name", n, "type", "wireguard"])
                    .await
                    .map_err(|e| {
                        Error::Network(format!(
                            "cannot create WireGuard interface {n} (is the wireguard kernel \
                             module available?): {e}"
                        ))
                    })?;
                self.ip(&["link", "set", "dev", n, "alias", WG_ALIAS])
                    .await?;
                rep.applied(format!("created {n}"));
            }
        }
        let conf = self.write_conf(n, &render_setconf(iface, peers))?;
        self.cmd
            .run("wg", &argv(&["syncconf", n, &conf.to_string_lossy()]))
            .await
            .map_err(|e| Error::Network(format!("wg syncconf {n}: {e}")))?;
        // addresses: exactly the configured ones (link-local v6 left alone)
        let want: Vec<IpNetwork> = networks(&iface.addresses);
        let have: Vec<IpNetwork> = k
            .get(n)
            .map(|l| {
                l.addrs
                    .iter()
                    .filter(|a| a.scope != "link")
                    .map(|a| a.net)
                    .collect()
            })
            .unwrap_or_default();
        for a in &have {
            if !want.contains(a) {
                self.ip(&["addr", "del", &a.to_string(), "dev", n]).await?;
            }
        }
        for a in &want {
            if !have.contains(a) {
                self.ip(&["addr", "add", &a.to_string(), "dev", n]).await?;
            }
        }
        let mtu = iface.mtu.unwrap_or(1420);
        if k.get(n).map(|l| l.mtu) != Some(mtu) {
            self.ip(&["link", "set", "dev", n, "mtu", &mtu.to_string()])
                .await?;
        }
        if !k.get(n).is_some_and(|l| l.up) {
            self.ip(&["link", "set", "dev", n, "up"]).await?;
        }
        // peer routes (protocol WG_PROTO), full state per device
        let want_routes: Vec<String> = peer_routes(iface, peers, rep)
            .iter()
            .map(|r| r.to_string())
            .collect();
        let have_routes = self.owned_routes(n).await?;
        for r in &have_routes {
            if !want_routes.contains(r) {
                self.ip(&["route", "del", r, "dev", n, "proto", WG_PROTO])
                    .await?;
            }
        }
        for r in &want_routes {
            if !have_routes.contains(r) {
                self.ip(&["route", "replace", r, "dev", n, "proto", WG_PROTO])
                    .await?;
            }
        }
        rep.applied(format!(
            "{n}: listening on UDP {}, {} peer(s), {} route(s)",
            iface.listen_port,
            peers.len(),
            want_routes.len()
        ));
        Ok(())
    }
}

#[async_trait]
impl Applier for WireGuardApplier {
    fn name(&self) -> &'static str {
        "wireguard"
    }

    fn phase(&self) -> Phase {
        Phase::Interfaces
    }

    fn resource_kinds(&self) -> &'static [patronus_config::ResourceKind] {
        &[patronus_config::ResourceKind::WireGuardTunnel]
    }

    async fn upsert_resource(
        &self,
        store: &ConfigStore,
        config: &patronus_config::DeclarativeConfig,
    ) -> Result<()> {
        let v = patronus_config::declarative::spec_value(config)?;
        gitops_upsert_tunnel(store, &config.metadata.name, v).await
    }

    async fn delete_resource(
        &self,
        store: &ConfigStore,
        _kind: &patronus_config::ResourceKind,
        name: &str,
    ) -> Result<()> {
        delete_interface(store, name).await?;
        Ok(())
    }

    async fn apply(&self, store: &ConfigStore) -> Result<ApplyReport> {
        let mut rep = ApplyReport::default();
        let ifaces = list_interfaces(store).await?;
        let peers = list_peers(store).await?;
        let k = KernelState::read(self.cmd.as_ref()).await?;
        let wanted: BTreeSet<&str> = ifaces
            .iter()
            .filter(|i| i.enabled)
            .map(|i| i.name.as_str())
            .collect();
        // tunnels that were deleted or disabled
        for l in k.links.values() {
            if l.kind.as_deref() == Some("wireguard")
                && l.alias.as_deref() == Some(WG_ALIAS)
                && !wanted.contains(l.name.as_str())
            {
                self.ip(&["link", "del", "dev", &l.name]).await?;
                rep.applied(format!("removed {}", l.name));
            }
        }
        if let Ok(rd) = std::fs::read_dir(&self.conf_dir) {
            for e in rd.flatten() {
                let f = e.file_name().to_string_lossy().into_owned();
                if let Some(n) = f.strip_suffix(".conf") {
                    if !wanted.contains(n) {
                        let _ = std::fs::remove_file(e.path());
                    }
                }
            }
        }
        let mut failed = Vec::new();
        for i in ifaces.iter().filter(|i| i.enabled) {
            let ps: Vec<&WgPeer> = peers
                .iter()
                .filter(|p| p.interface == i.name && p.enabled)
                .collect();
            if let Err(e) = self.apply_one(i, &ps, &k, &mut rep).await {
                failed.push(format!("{}: {e}", i.name));
            }
        }
        if ifaces.is_empty() {
            rep.applied("no WireGuard tunnels configured");
        }
        if !failed.is_empty() {
            return Err(Error::Network(failed.join("; ")));
        }
        Ok(rep)
    }

    async fn render(&self, store: &ConfigStore) -> Result<String> {
        let ifaces = list_interfaces(store).await?;
        let peers = list_peers(store).await?;
        let mut out = String::new();
        for i in ifaces.iter().filter(|i| i.enabled) {
            let redacted = WgInterface {
                private_key: "(hidden)".into(),
                ..i.clone()
            };
            let ps: Vec<WgPeer> = peers
                .iter()
                .filter(|p| p.interface == i.name && p.enabled)
                .map(|p| WgPeer {
                    preshared_key: p.preshared_key.as_ref().map(|_| "(hidden)".into()),
                    ..p.clone()
                })
                .collect();
            let refs: Vec<&WgPeer> = ps.iter().collect();
            out.push_str(&format!(
                "## {} ({}; addresses {}, mtu {})\n{}",
                i.name,
                self.conf_dir.join(format!("{}.conf", i.name)).display(),
                if i.addresses.is_empty() {
                    "none"
                } else {
                    &i.addresses
                },
                i.mtu.unwrap_or(1420),
                render_setconf(&redacted, &refs)
            ));
        }
        if out.is_empty() {
            out.push_str("# no WireGuard tunnels\n");
        }
        Ok(out)
    }

    async fn status(&self, _store: &ConfigStore) -> Result<Value> {
        let k = KernelState::read(self.cmd.as_ref()).await?;
        let links: Vec<Value> = k
            .links
            .values()
            .filter(|l| l.kind.as_deref() == Some("wireguard"))
            .map(|l| {
                json!({"name": l.name, "up": l.up, "managed": l.alias.as_deref() == Some(WG_ALIAS)})
            })
            .collect();
        Ok(json!({ "links": links }))
    }
}

